-- The cases of test_run_sql_join_kinds: each COPY line below is one case, the
-- query DuckDB runs over the tables of data.sql (l, r, n, e and big, each a
-- `.parquet` file) and the file its answer goes to. The test reads THIS FILE
-- for the query text and runs the same text through run_sql with each file
-- name replaced by its path, so a query has one source. A case's name is its
-- output file without `.tsv`.
COPY (SELECT l.lk AS lk, l.ls AS ls, l.li AS li, l.lv AS lv, r.rk AS rk, r.rs AS rs, r.ri AS ri, r.rv AS rv FROM read_parquet('l.parquet') l LEFT JOIN read_parquet('r.parquet') r ON l.lk = r.rk) TO 'left_rows.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.li AS li, l.lv AS lv, r.rk AS rk, r.rs AS rs, r.ri AS ri, r.rv AS rv FROM read_parquet('l.parquet') l RIGHT JOIN read_parquet('r.parquet') r ON l.lk = r.rk) TO 'right_rows.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.li AS li, l.lv AS lv, r.rk AS rk, r.rs AS rs, r.ri AS ri, r.rv AS rv FROM read_parquet('l.parquet') l FULL OUTER JOIN read_parquet('r.parquet') r ON l.lk = r.rk) TO 'full_rows.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.li AS li, l.lv AS lv, r.rk AS rk, r.rs AS rs, r.ri AS ri, r.rv AS rv FROM read_parquet('l.parquet') l LEFT OUTER JOIN read_parquet('r.parquet') r ON l.lk = r.rk) TO 'left_outer_keyword.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.li AS li, l.lv AS lv, r.rk AS rk, r.rs AS rs, r.ri AS ri, r.rv AS rv FROM read_parquet('l.parquet') l LEFT JOIN read_parquet('r.parquet') r ON l.ls = r.rs) TO 'left_string.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.li AS li, l.lv AS lv, r.rk AS rk, r.rs AS rs, r.ri AS ri, r.rv AS rv FROM read_parquet('l.parquet') l RIGHT JOIN read_parquet('r.parquet') r ON l.ls = r.rs) TO 'right_string.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.li AS li, l.lv AS lv, r.rk AS rk, r.rs AS rs, r.ri AS ri, r.rv AS rv FROM read_parquet('l.parquet') l FULL JOIN read_parquet('r.parquet') r ON l.ls = r.rs) TO 'full_string.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.li AS li, l.lv AS lv, r.rk AS rk, r.rs AS rs, r.ri AS ri, r.rv AS rv FROM read_parquet('l.parquet') l LEFT JOIN read_parquet('r.parquet') r ON l.li = r.rk) TO 'left_int32_int64.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.li AS li, l.lv AS lv, r.rk AS rk, r.rs AS rs, r.ri AS ri, r.rv AS rv FROM read_parquet('l.parquet') l RIGHT JOIN read_parquet('r.parquet') r ON l.li = r.rk) TO 'right_int32_int64.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.li AS li, l.lv AS lv, r.rk AS rk, r.rs AS rs, r.ri AS ri, r.rv AS rv FROM read_parquet('l.parquet') l FULL JOIN read_parquet('r.parquet') r ON l.li = r.rk) TO 'full_int32_int64.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.li AS li, l.lv AS lv, r.rk AS rk, r.rs AS rs, r.ri AS ri, r.rv AS rv FROM read_parquet('l.parquet') l FULL JOIN read_parquet('r.parquet') r ON l.li = r.ri) TO 'full_int32_int32.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ld AS ld, r.rk AS rk, r.rd AS rd FROM read_parquet('l.parquet') l LEFT JOIN read_parquet('r.parquet') r ON l.ld = r.rd) TO 'left_double.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ld AS ld, r.rk AS rk, r.rd AS rd FROM read_parquet('l.parquet') l FULL JOIN read_parquet('r.parquet') r ON l.ld = r.rd) TO 'full_double.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.li AS li, l.lv AS lv, r.rk AS rk, r.rs AS rs, r.ri AS ri, r.rv AS rv FROM read_parquet('l.parquet') l LEFT JOIN read_parquet('r.parquet') r ON l.lk = r.rk AND l.ls = r.rs) TO 'left_two_keys.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.li AS li, l.lv AS lv, r.rk AS rk, r.rs AS rs, r.ri AS ri, r.rv AS rv FROM read_parquet('l.parquet') l RIGHT JOIN read_parquet('r.parquet') r ON l.lk = r.rk AND l.ls = r.rs) TO 'right_two_keys.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.li AS li, l.lv AS lv, r.rk AS rk, r.rs AS rs, r.ri AS ri, r.rv AS rv FROM read_parquet('l.parquet') l FULL JOIN read_parquet('r.parquet') r ON l.lk = r.rk AND l.ls = r.rs) TO 'full_two_keys.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, count(*) AS n, count(r.rv) AS nv, sum(r.rv) AS total FROM read_parquet('l.parquet') l LEFT JOIN read_parquet('r.parquet') r ON l.lk = r.rk GROUP BY l.lk) TO 'left_count.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT r.rk AS rk, count(*) AS n, count(l.lv) AS nv FROM read_parquet('l.parquet') l RIGHT JOIN read_parquet('r.parquet') r ON l.lk = r.rk GROUP BY r.rk) TO 'right_count.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT count(*) AS n, count(l.lk) AS nl, count(r.rk) AS nr FROM read_parquet('l.parquet') l FULL JOIN read_parquet('r.parquet') r ON l.lk = r.rk) TO 'full_count.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.li AS li, l.lv AS lv, r.rk AS rk, r.rs AS rs, r.ri AS ri, r.rv AS rv FROM read_parquet('l.parquet') l LEFT JOIN read_parquet('r.parquet') r ON l.lk = r.rk AND r.rv > 500) TO 'left_right_conjunct.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.lv AS lv FROM read_parquet('l.parquet') l LEFT JOIN read_parquet('r.parquet') r ON l.lk = r.rk WHERE r.rk IS NULL) TO 'left_anti_idiom.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.li AS li, l.lv AS lv, r.rk AS rk, r.rs AS rs, r.ri AS ri, r.rv AS rv FROM read_parquet('l.parquet') l LEFT JOIN read_parquet('r.parquet') r ON l.lk = r.rk WHERE l.lv > 100) TO 'left_where_left.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, r.rv AS rv, n.nk AS nk FROM read_parquet('l.parquet') l LEFT JOIN read_parquet('r.parquet') r ON l.lk = r.rk LEFT JOIN read_parquet('n.parquet') n ON l.lk = n.nk) TO 'left_chain.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.lv AS lv, r.rv AS rv, n.nk AS nk FROM read_parquet('l.parquet') l JOIN read_parquet('r.parquet') r ON l.lk = r.rk RIGHT JOIN read_parquet('n.parquet') n ON r.rk = n.nk) TO 'inner_then_right.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.li AS li, l.lv AS lv, e.rk AS rk, e.rv AS rv FROM read_parquet('l.parquet') l LEFT JOIN read_parquet('e.parquet') e ON l.lk = e.rk) TO 'left_empty_build.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT e.rk AS rk, e.rv AS rv, l.lk AS lk, l.ls AS ls, l.li AS li, l.lv AS lv FROM read_parquet('e.parquet') e LEFT JOIN read_parquet('l.parquet') l ON e.rk = l.lk) TO 'left_empty_probe.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.li AS li, l.lv AS lv, e.rk AS rk, e.rv AS rv FROM read_parquet('l.parquet') l RIGHT JOIN read_parquet('e.parquet') e ON l.lk = e.rk) TO 'right_empty_build.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT e.rk AS rk, e.rv AS rv, l.lk AS lk, l.ls AS ls, l.li AS li, l.lv AS lv FROM read_parquet('e.parquet') e RIGHT JOIN read_parquet('l.parquet') l ON e.rk = l.lk) TO 'right_empty_probe.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.li AS li, l.lv AS lv, e.rk AS rk, e.rv AS rv FROM read_parquet('l.parquet') l FULL JOIN read_parquet('e.parquet') e ON l.lk = e.rk) TO 'full_empty_build.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT e.rk AS rk, e.rv AS rv, l.lk AS lk, l.ls AS ls, l.li AS li, l.lv AS lv FROM read_parquet('e.parquet') e FULL JOIN read_parquet('l.parquet') l ON e.rk = l.lk) TO 'full_empty_probe.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.lv AS lv FROM read_parquet('l.parquet') l WHERE EXISTS (SELECT 1 FROM read_parquet('r.parquet') r WHERE r.rk = l.lk)) TO 'exists.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.lv AS lv FROM read_parquet('l.parquet') l WHERE EXISTS (SELECT 1 FROM read_parquet('r.parquet') r WHERE r.rk = l.lk AND r.rv > 500)) TO 'exists_inner_filter.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.lv AS lv FROM read_parquet('l.parquet') l WHERE EXISTS (SELECT 1 FROM read_parquet('r.parquet') r WHERE r.rk = l.lk AND r.rs = l.ls)) TO 'exists_two_keys.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.lv AS lv FROM read_parquet('l.parquet') l WHERE EXISTS (SELECT 1 FROM read_parquet('r.parquet') r WHERE r.rs = l.ls)) TO 'exists_string.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.lv AS lv FROM read_parquet('l.parquet') l WHERE NOT EXISTS (SELECT 1 FROM read_parquet('r.parquet') r WHERE r.rk = l.lk)) TO 'not_exists.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.lv AS lv FROM read_parquet('l.parquet') l WHERE NOT EXISTS (SELECT 1 FROM read_parquet('r.parquet') r WHERE r.rk = l.lk AND r.rs = l.ls)) TO 'not_exists_two_keys.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.lv AS lv FROM read_parquet('l.parquet') l WHERE EXISTS (SELECT 1 FROM read_parquet('e.parquet') e WHERE e.rk = l.lk)) TO 'exists_empty.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.lv AS lv FROM read_parquet('l.parquet') l WHERE NOT EXISTS (SELECT 1 FROM read_parquet('e.parquet') e WHERE e.rk = l.lk)) TO 'not_exists_empty.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.lv AS lv FROM read_parquet('l.parquet') l WHERE l.lk IN (SELECT r.rk FROM read_parquet('r.parquet') r)) TO 'in_subquery.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.lv AS lv FROM read_parquet('l.parquet') l WHERE l.li IN (SELECT r.rk FROM read_parquet('r.parquet') r)) TO 'in_int32_int64.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.lv AS lv FROM read_parquet('l.parquet') l WHERE l.ls IN (SELECT r.rs FROM read_parquet('r.parquet') r)) TO 'in_string.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.lv AS lv FROM read_parquet('l.parquet') l SEMI JOIN read_parquet('r.parquet') r ON l.lk = r.rk) TO 'semi_keyword.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.lv AS lv FROM read_parquet('l.parquet') l ANTI JOIN read_parquet('r.parquet') r ON l.lk = r.rk) TO 'anti_keyword.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT count(*) AS n FROM read_parquet('l.parquet') l WHERE EXISTS (SELECT 1 FROM read_parquet('r.parquet') r WHERE r.rk = l.lk)) TO 'semi_count.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.lv AS lv FROM read_parquet('l.parquet') l WHERE l.lk NOT IN (SELECT r.rk FROM read_parquet('r.parquet') r)) TO 'not_in_with_nulls.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.lv AS lv FROM read_parquet('l.parquet') l WHERE l.lk NOT IN (SELECT n.nk FROM read_parquet('n.parquet') n)) TO 'not_in_null_free.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.lv AS lv FROM read_parquet('l.parquet') l WHERE l.lk NOT IN (SELECT r.rk FROM read_parquet('r.parquet') r WHERE r.rv > 100000)) TO 'not_in_empty_filtered.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.lv AS lv FROM read_parquet('l.parquet') l WHERE l.lk NOT IN (SELECT e.rk FROM read_parquet('e.parquet') e)) TO 'not_in_empty_table.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.lv AS lv FROM read_parquet('l.parquet') l WHERE l.lk NOT IN (SELECT r.rk FROM read_parquet('r.parquet') r WHERE r.rk IS NOT NULL)) TO 'not_in_nulls_filtered.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.lv AS lv FROM read_parquet('l.parquet') l WHERE l.ls NOT IN (SELECT r.rs FROM read_parquet('r.parquet') r WHERE r.rs IS NOT NULL)) TO 'not_in_string_nulls_filtered.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.lv AS lv FROM read_parquet('l.parquet') l WHERE l.ls NOT IN (SELECT r.rs FROM read_parquet('r.parquet') r)) TO 'not_in_string_with_nulls.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT n.nk AS nk, r.rs AS rs, r.rv AS rv FROM read_parquet('n.parquet') n CROSS JOIN read_parquet('r.parquet') r) TO 'cross_rows.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.lv AS lv, n.nk AS nk FROM read_parquet('l.parquet') l, read_parquet('n.parquet') n) TO 'comma_rows.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT count(*) AS cnt, count(r.rv) AS nv FROM read_parquet('l.parquet') l CROSS JOIN read_parquet('r.parquet') r) TO 'cross_count.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT n.nk AS nk, e.rk AS rk FROM read_parquet('n.parquet') n CROSS JOIN read_parquet('e.parquet') e) TO 'cross_empty_build.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT e.rk AS rk, n.nk AS nk FROM read_parquet('e.parquet') e CROSS JOIN read_parquet('n.parquet') n) TO 'cross_empty_probe.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT count(*) AS cnt, sum(a.bk + b.bk) AS total FROM read_parquet('big.parquet') a CROSS JOIN read_parquet('big.parquet') b) TO 'cross_chunked.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.lv AS lv FROM read_parquet('l.parquet') l WHERE l.lv * 10 > (SELECT max(r.rv) FROM read_parquet('r.parquet') r)) TO 'scalar_max.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l.lk AS lk, l.ls AS ls, l.lv AS lv FROM read_parquet('l.parquet') l WHERE l.lv > (SELECT count(*) FROM read_parquet('r.parquet') r)) TO 'scalar_count.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
